from pathlib import Path
import base64, gzip, hashlib

ROOT = Path(__file__).resolve().parent

def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()

PAYLOADS = {
    'source': ('OKNO_MSK_RESEARCH_RELEASE_CORRECTED_2026-09-05/sources/01_OKNO_MSK_CLIENT_RESEARCH_REPORT_RU_2026-09-05.md', '', '232030778a3c7378d35dc10397f48f0262d4facd043ecc111c51d711ac49caff', 51321),
    'builder': ('document01_build_commissioner_report.py', '', 'fb3d9020d538ab7d3b1b21bbca2ad538060976c69d4b3e6169ac1d430f55802f', 13717),
    'qa': ('document01_commissioner_recipient_qa.py', '', 'c5c597a612c11312d410a106e4eac8d43e3ee16ccd2a91957a8509a4424638c6', 15727),
    'gate': ('../../STEP_20_REPORT_01_CUSTOMER_RESEARCH_REPORT_GATE.md', '', '4fbc849b897b1987de72118c11f3f42068ce2588ecbbaf182f7f4a8daaa0d0f3', 8750),
}

for name, (rel, encoded, expected_sha, expected_size) in PAYLOADS.items():
    data = gzip.decompress(base64.b64decode(encoded))
    assert len(data) == expected_size, (name, len(data), expected_size)
    assert sha256_bytes(data) == expected_sha, (name, sha256_bytes(data), expected_sha)
    path = (ROOT / rel).resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    assert path.stat().st_size == expected_size
    assert sha256_bytes(path.read_bytes()) == expected_sha
    print('MATERIALIZED', name, path, expected_size, expected_sha)

text = (ROOT / PAYLOADS['source'][0]).read_text(encoding='utf-8')
required = [
    '# ОКНО МОСКВА — поисковое ядро сайта: спрос, обычный Яндекс и ответы Алисы',
    'Задача работы — пересобрать поисковое ядро сайта для Москвы',
    '168 групп поискового спроса',
    'а не отдельным предметом исследования',
    'а не 2 840 отдельных замеров точной частотности',
    'Что дала проверка ответов Алисы'
]
for marker in required:
    assert marker in text, marker
for forbidden in ['2 840 точных поисковых формулировок', 'пользовательских задач и подзадач', 'спорные семьи', 'изменения запрещены', 'частично готовая работа']:
    assert forbidden.lower() not in text.lower(), forbidden

print('DOCUMENT_01_SEMANTIC_CORE_MATERIALIZATION_PASS')
